{
  "title": "迷雾森林的隐秘花园",
  "scene": "你正漫步在一片笼罩着淡淡晨雾的古老森林中。阳光透过稀疏的树冠，洒下斑驳的光影。你偶然发现了一条隐藏的小径，通向一片被绿色灌木丛包围的隐秘花园。花园里有几座古老的石雕和一池清澈的池水，池边盛开着奇异的花朵，散发着淡淡的香气。",
  "goal": "探索花园的秘密，找到隐藏在花园中的古老石刻，了解它们背后的故事。",
  "choices": [
    {
      "id": "A",
      "text": "仔细观察花园中的每一处细节，试图找到线索。",
      "outcome": "你发现了一本古老的手册散落在花园角落，上面记载着关于这些石刻的传说。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "B",
      "text": "靠近池水，小心地触摸那些奇异的花朵。",
      "outcome": "你感受到一阵温和的微风，花朵似乎在回应你的触摸，但并没有获取到新的线索。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "C",
      "text": "爬上附近的一棵树，从树冠上俯瞰整个花园。",
      "outcome": "你发现花园的角落有一个隐蔽的小门，似乎通向花园的另一个隐蔽区域。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
